@[ext]
theorem LeftInvariantMetric.ext {g h : LeftInvariantMetric}
    (hgram : g.gram = h.gram) : g = h

theorem fixes_cometric {a : InnerAction} {g : LeftInvariantMetric}
    (hfix : Fixes a g) :
    (innerMatrix a)ᵀ * g.gram⁻¹ * innerMatrix a = g.gram⁻¹

lemma diagonalize_orthogonal_rows {a b c e : ℝ}
    (hnorm : 0 < a ^ 2 + b ^ 2) (horth : a * c + b * e = 0) :
    ∃ Q : SO2, IsDiagonal2 (!![a, b; c, e] * (Q : Mat2)ᵀ)

lemma diagonalize_orthogonal_columns {a b c e : ℝ}
    (hnorm : 0 < a ^ 2 + c ^ 2) (horth : a * b + c * e = 0) :
    ∃ Q : SO2, IsDiagonal2 ((Q : Mat2) * !![a, b; c, e])

theorem containsKleinFour_of_diagonal_turns {g : LeftInvariantMetric}
    (h₁ : Fixes diagonalTurn1 g) (h₂ : Fixes diagonalTurn2 g) :
    ContainsKleinFour g

lemma isDiagonal2_cross_of_left_diagonalized (P : SO2) {N : Mat2}
    (s : ℝ) (hPN : IsDiagonal2 ((P : Mat2) * N)) :
    IsDiagonal2 (Nᵀ * (diag2 s s * (P : Mat2)ᵀ))

lemma standardFixed_transpose {X : Mat3}
    (hX : (halfTurn1 : Mat3)ᵀ * X * halfTurn1 = X) :
    (halfTurn1 : Mat3)ᵀ * Xᵀ * halfTurn1 = Xᵀ

lemma standardFixed_inv {X : Mat3}
    (hX : (halfTurn1 : Mat3)ᵀ * X * halfTurn1 = X) :
    (halfTurn1 : Mat3)ᵀ * X⁻¹ * halfTurn1 = X⁻¹

theorem containsKleinFour_of_pullback {g : LeftInvariantMetric}
    (a : InnerAction) (hK : ContainsKleinFour (pullbackMetric a g)) :
    ContainsKleinFour g

lemma eulerForGraph_M_det_ne_zero {g : LeftInvariantMetric}
    (d : GraphData g) {lambda : ℝ}
    (hEin : ricci g = lambda • g.gram) (hMdet : d.M.det ≠ 0) :
    (eulerForGraph d hEin).euler.M.det ≠ 0

lemma nontrivial_of_eulerForGraph_ell_zero {g : LeftInvariantMetric}
    (d : GraphData g) {lambda : ℝ}
    (hEin : ricci g = lambda • g.gram)
    (hMdet : d.M.det ≠ 0)
    (hell : ell (eulerForGraph d hEin).euler = 0) :
    HasNontrivialInnerIsotropy g

lemma threshold_four_small_middle {r s t : ℝ}
    (_hr : 0 < r) (hrs : r ≤ s) (hs : s < 2) (ht : 4 ≤ t) :
    0 < r * s - 2 * r - 2 * s + 2 * t

lemma threshold_four_scalar {r s t : ℝ}
    (hr : 0 < r) (hrs : r ≤ s) (hst : s ≤ t) (ht : 4 ≤ t) :
    0 < r * s - 2 * r - 2 * s + 2 * t

lemma theta_large_iff {a b S theta : ℝ}
    (ha : 0 < a) (hb : 0 < b) (hS : 0 < S) :
    S / b * (b - a * theta) < 0 ↔ b / a < theta

lemma twoOfThree_intersection {A B : I3 → Prop}
    (hA : TwoOfThree A) (hB : TwoOfThree B) :
    ∃ i, A i ∧ B i

lemma edge_product_zero_of_missing {x : I3 → ℝ} {i r : I3}
    (hmiss : MissingOnly x i) (hri : r ≠ i) :
    x (jIndex r) * x (kIndex r) = 0

lemma residual_eq_diag_of_missing {p x : I3 → ℝ} {i r : I3}
    (hmiss : MissingOnly x i) (hri : r ≠ i) :
    edgeResidual (symm3 p x) r = p r

lemma rawOfDiagonalGraph_P {g : LeftInvariantMetric}
    (d : GraphData g) (p q : I3 → ℝ) (hp : ∀ i, 0 < p i) :
    (rawOfDiagonalGraph d p q).P = Matrix.diagonal p

lemma rawOfDiagonalGraph_Q {g : LeftInvariantMetric}
    (d : GraphData g) (p q : I3 → ℝ) (hq : ∀ i, 0 < q i) :
    (rawOfDiagonalGraph d p q).Q = Matrix.diagonal q

lemma swappedPClosed_posDef {g : LeftInvariantMetric}
    (d : GraphData g) (m : I3 → ℝ) :
    (swappedPClosed d m).PosDef

lemma swappedQClosed_posDef {g : LeftInvariantMetric}
    (d : GraphData g) (m : I3 → ℝ) :
    (swappedQClosed d m).PosDef

lemma edge_zero_of_scaled_edge_zero {A B : Mat3} {t : ℝ}
    (ht : t ≠ 0) (hAB : A = t • B) (i : I3)
    (hA : edgeOf A i = 0) : edgeOf B i = 0

lemma trace_smul_one_sub_posSemidef_three {A : Mat3}
