lemma barrierTransfer_det_ne_zero {g : LeftInvariantMetric}
    (d : GraphData g) (m : I3 → ℝ) (t : ℝ) (ht : 0 < t) :
    (barrierTransferMatrix d m t).det ≠ 0

theorem nontrivial_of_swap {g : LeftInvariantMetric}
